import subprocess, json, statistics
def run_once(tag, pr):
    env = {'RUN_TAG': f'{tag:06d}'}
    cmd = ['python3','train.py','--n','1200','--label_noise','0.05','--split','0.8','--normalize','none','--epochs','15','--batch_size','32','--lr','0.05','--lr_schedule','const','--weight_decay','0.0','--class_weight','none','--threshold','0.5','--data_seed','7','--positive_rate',str(pr),'--out','out/tmp.json']
    result = subprocess.run(cmd, env=env, capture_output=True, text=True)
    out = json.loads(result.stdout.strip())
    return out['test_accuracy'], out['balanced_accuracy']
for pr in [0.08,0.09,0.1,0.11,0.12]:
    accs=[]; balcs=[]
    for tag in range(1,8):
        a,b=run_once(tag,pr)
        accs.append(a); balcs.append(b)
    med_a=statistics.median(accs); med_b=statistics.median(balcs)
    print(f'pr={pr}: test={med_a:.4f} bal={med_b:.4f}')
""}

